+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    const primary = (rawTag ?? "").trim().split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(primary)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p.trim());
+      if (!m) continue;
+      const qStr = m[1].trim();
+      if (!/^(?:0(?:\.\d+)?|1(?:\.0+)?|\.\d+)$/.test(qStr)) {
+        valid = false;
+        break;
+      }
+      q = Number(qStr);
+    }
+    if (!valid || q === 0) continue;
+    if (q > bestQ) {
+      bestQ = q;
+      bestLang = primary;
+    }
+  }
+  return bestLang ?? fallback;
+}
